From c09e87fefe824aac2b72ab1ce7e0a3926434a6d0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:52:06 +0100
Subject: [PATCH] containmentitem: support mouse actions on double-click

ContainmentActions::eventToString() gave a double-click the same trigger
as a press, so no action could be assigned to it. Give it a separate
"doubleclick:" trigger and run its action from ContainmentItem.

BUG: 409616
---
 src/plasma/containmentactions.cpp            |  3 +++
 src/plasmaquick/plasmoid/containmentitem.cpp | 18 +++++++++++++++++-
 src/plasmaquick/plasmoid/containmentitem.h   |  1 +
 3 files changed, 21 insertions(+), 1 deletion(-)

diff --git a/src/plasma/containmentactions.cpp b/src/plasma/containmentactions.cpp
index 2d6f878f1..916120508 100644
--- a/src/plasma/containmentactions.cpp
+++ b/src/plasma/containmentactions.cpp
@@ -118,6 +118,9 @@ QString ContainmentActions::eventToString(QEvent *event)
         QMouseEvent *e = static_cast<QMouseEvent *>(event);
         int m = mo.indexOfEnumerator("MouseButtons");
         QMetaEnum mouse = mo.enumerator(m);
+        if (event->type() == QEvent::MouseButtonDblClick) {
+            trigger = QStringLiteral("doubleclick:");
+        }
         trigger += QString::fromLatin1(mouse.valueToKey(e->button()));
         modifiers = e->modifiers();
         break;
diff --git a/src/plasmaquick/plasmoid/containmentitem.cpp b/src/plasmaquick/plasmoid/containmentitem.cpp
index d8f65fc21..2a6f1063b 100644
--- a/src/plasmaquick/plasmoid/containmentitem.cpp
+++ b/src/plasmaquick/plasmoid/containmentitem.cpp
@@ -807,7 +807,18 @@ void ContainmentItem::mousePressEvent(QMouseEvent *event)
     Plasma::ContainmentActions *plugin = m_containment->containmentActions().value(trigger);

     if (!plugin) {
-        event->setAccepted(false);
+        // Keep the press if this button has a double-click action, so that the double-click reaches us
+        if (event->type() == QEvent::MouseButtonPress) {
+            QMouseEvent doubleClick(QEvent::MouseButtonDblClick,
+                                    event->position(),
+                                    event->globalPosition(),
+                                    event->button(),
+                                    event->buttons(),
+                                    event->modifiers());
+            event->setAccepted(m_containment->containmentActions().contains(Plasma::ContainmentActions::eventToString(&doubleClick)));
+        } else {
+            event->setAccepted(false);
+        }
         return;
     }

@@ -905,6 +916,11 @@ void ContainmentItem::mousePressEvent(QMouseEvent *event)
     event->setAccepted(true);
 }

+void ContainmentItem::mouseDoubleClickEvent(QMouseEvent *event)
+{
+    mousePressEvent(event);
+}
+
 void ContainmentItem::wheelEvent(QWheelEvent *event)
 {
     const QString trigger = Plasma::ContainmentActions::eventToString(event);
diff --git a/src/plasmaquick/plasmoid/containmentitem.h b/src/plasmaquick/plasmoid/containmentitem.h
index 306f5b423..8d7c8e8a1 100644
--- a/src/plasmaquick/plasmoid/containmentitem.h
+++ b/src/plasmaquick/plasmoid/containmentitem.h
@@ -123,6 +123,7 @@ protected:
     void loadWallpaper();
     void mousePressEvent(QMouseEvent *event) override;
     void mouseReleaseEvent(QMouseEvent *event) override;
+    void mouseDoubleClickEvent(QMouseEvent *event) override;
     void wheelEvent(QWheelEvent *event) override;
     void keyPressEvent(QKeyEvent *event) override;

-- 
2.53.0

From f905463d11a5e83416a9d3b492c521ffdf0b9685 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:52:07 +0100
Subject: [PATCH] desktop: support mouse actions on double-click

Folder View takes clicks on empty space and replays them to the desktop
as a press, so a double-click never reached the mouse actions. Replay it
too, and let the mouse actions page record and show double-clicks.

BUG: 409616
---
 .../package/contents/ui/FolderView.qml        | 16 +++++++
 .../desktop/plugins/folder/eventgenerator.cpp |  3 ++
 .../desktop/plugins/folder/eventgenerator.h   |  1 +
 .../ConfigurationContainmentActions.qml       | 11 ++++-
 .../configuration/MouseEventInputButton.qml   | 45 ++++++++++++++-----
 5 files changed, 63 insertions(+), 13 deletions(-)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..6fed7eadc4 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -364,6 +364,14 @@ FocusScope {
             if (!hoveredItem || hoveredItem.blank || gridView.currentIndex === -1 || gridView.ctrlPressed || gridView.shiftPressed) {
                 // Bug 357367: Replay mouse event, so containment actions assigned to left mouse button work.
                 eventGenerator.sendMouseEvent(root, Folder.EventGenerator.MouseButtonPress, mouse.x, mouse.y, mouse.button, mouse.buttons, mouse.modifiers);
+                // Also replay double-clicks, for containment actions assigned to them
+                if (replayDoubleClickTimer.running && replayDoubleClickTimer.button === mouse.button) {
+                    replayDoubleClickTimer.stop();
+                    eventGenerator.sendMouseEvent(root, Folder.EventGenerator.MouseButtonDblClick, mouse.x, mouse.y, mouse.button, mouse.buttons, mouse.modifiers);
+                } else {
+                    replayDoubleClickTimer.button = mouse.button;
+                    replayDoubleClickTimer.restart();
+                }
                 return;
             }

@@ -607,6 +615,14 @@ FocusScope {
             }
         }

+        Timer {
+            id: replayDoubleClickTimer
+
+            property int button: Qt.NoButton
+
+            interval: Application.styleHints.mouseDoubleClickInterval
+        }
+
         Timer {
             id: hoverActivateTimer

diff --git a/containments/desktop/plugins/folder/eventgenerator.cpp b/containments/desktop/plugins/folder/eventgenerator.cpp
index c3395824f4..abce3e7f98 100644
--- a/containments/desktop/plugins/folder/eventgenerator.cpp
+++ b/containments/desktop/plugins/folder/eventgenerator.cpp
@@ -43,6 +43,9 @@ void EventGenerator::sendMouseEvent(QQuickItem *item,
     case MouseMove:
         eventType = QEvent::MouseMove;
         break;
+    case MouseButtonDblClick:
+        eventType = QEvent::MouseButtonDblClick;
+        break;
     default:
         return;
     }
diff --git a/containments/desktop/plugins/folder/eventgenerator.h b/containments/desktop/plugins/folder/eventgenerator.h
index f6b8dde450..af40c958b0 100644
--- a/containments/desktop/plugins/folder/eventgenerator.h
+++ b/containments/desktop/plugins/folder/eventgenerator.h
@@ -23,6 +23,7 @@ public:
         MouseButtonPress,
         MouseButtonRelease,
         MouseMove,
+        MouseButtonDblClick,
     };
     Q_ENUM(MouseEvent)

diff --git a/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml b/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml
index 5cac407e79..c0ef469946 100644
--- a/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml
+++ b/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml
@@ -60,6 +60,10 @@ KCM.SimpleKCM {
                     var splitAction = model.action.split(';');

                     var button = splitAction[0];
+                    var doubleClick = button.startsWith("doubleclick:");
+                    if (doubleClick) {
+                        button = button.slice("doubleclick:".length);
+                    }
                     var modifiers = (splitAction[1] || "").split('|').filter(function (item) {
                         return item !== "NoModifier";
                     });
@@ -67,9 +71,14 @@ KCM.SimpleKCM {
                     var parts = modifiers;
                     modifiers.push(button);

-                    return parts.map(function (item) {
+                    var shortcut = parts.map(function (item) {
                         return root.prettyStrings[item] || item;
                     }).join(i18ndc("plasma_shell_org.kde.plasma.desktop", "Concatenation sign for shortcuts, e.g. Ctrl+Shift", "+"));
+
+                    if (doubleClick) {
+                        return i18ndc("plasma_shell_org.kde.plasma.desktop", "@label for shortcuts, %1 is a mouse button with optional modifiers, e.g. Ctrl+Left-Button", "%1 Double-Click", shortcut);
+                    }
+                    return shortcut;
                 }
                 eventString: model.action
                 onEventStringChanged: {
diff --git a/desktoppackage/contents/configuration/MouseEventInputButton.qml b/desktoppackage/contents/configuration/MouseEventInputButton.qml
index aeb4f83071..68598d60b3 100644
--- a/desktoppackage/contents/configuration/MouseEventInputButton.qml
+++ b/desktoppackage/contents/configuration/MouseEventInputButton.qml
@@ -21,6 +21,31 @@ QQC2.Button {
             mouseInputArea.enabled = true;
         }
     }
+
+    function setEventString(newEventString: string) {
+        if (mouseInputButton.eventString === newEventString || !configDialog.currentContainmentActionsModel.isTriggerUsed(newEventString)) {
+            if (mouseInputButton.eventString === newEventString) {
+                // fire changed signal so deleted button can return if needed
+                mouseInputButton.eventStringChanged()
+            } else {
+                mouseInputButton.eventString = newEventString;
+            }
+            mouseInputButton.text = mouseInputButton.defaultText;
+            mouseInputButton.checked = false;
+            mouseInputArea.enabled = false;
+        }
+    }
+
+    Timer {
+        id: pendingClickTimer
+
+        property int button
+        property int modifiers
+
+        interval: Application.styleHints.mouseDoubleClickInterval
+        onTriggered: mouseInputButton.setEventString(configDialog.currentContainmentActionsModel.mouseEventString(button, modifiers))
+    }
+
     MouseArea {
         id: mouseInputArea
         anchors.fill: parent
@@ -28,19 +53,15 @@ QQC2.Button {
         enabled: false

         onClicked: mouse => {
-            var newEventString = configDialog.currentContainmentActionsModel.mouseEventString(mouse.button, mouse.modifiers);
+            // Wait to see whether this is the first click of a double-click
+            pendingClickTimer.button = mouse.button;
+            pendingClickTimer.modifiers = mouse.modifiers;
+            pendingClickTimer.restart();
+        }

-            if (mouseInputButton.eventString === newEventString || !configDialog.currentContainmentActionsModel.isTriggerUsed(newEventString)) {
-                if (mouseInputButton.eventString === newEventString) {
-                    // fire changed signal so deleted button can return if needed
-                    mouseInputButton.eventStringChanged()
-                } else {
-                    mouseInputButton.eventString = newEventString;
-                }
-                mouseInputButton.text = mouseInputButton.defaultText;
-                mouseInputButton.checked = false;
-                enabled = false;
-            }
+        onDoubleClicked: mouse => {
+            pendingClickTimer.stop();
+            mouseInputButton.setEventString(configDialog.currentContainmentActionsModel.mouseDoubleClickEventString(mouse.button, mouse.modifiers));
         }

         onWheel: wheel => {
-- 
