From fb99fbc8f261f0f20831f91623af215e070914be Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:52:06 +0100
Subject: [PATCH] shell: let the mouse actions model make double-click triggers

The mouse actions page could only turn single clicks and wheel events
into triggers. Add a method that returns the trigger of a double-click,
so that the page can record actions for double-clicks too.

BUG: 409616
---
 shell/currentcontainmentactionsmodel.cpp | 7 +++++++
 shell/currentcontainmentactionsmodel.h   | 1 +
 2 files changed, 8 insertions(+)

diff --git a/shell/currentcontainmentactionsmodel.cpp b/shell/currentcontainmentactionsmodel.cpp
index 5af2e66591..86755354e6 100644
--- a/shell/currentcontainmentactionsmodel.cpp
+++ b/shell/currentcontainmentactionsmodel.cpp
@@ -76,6 +76,13 @@ QString CurrentContainmentActionsModel::mouseEventString(int mouseButton, int mo
     return string;
 }

+QString CurrentContainmentActionsModel::mouseDoubleClickEventString(int mouseButton, int modifiers)
+{
+    QMouseEvent mouse(QEvent::MouseButtonDblClick, QPoint(), (Qt::MouseButton)mouseButton, (Qt::MouseButton)mouseButton, (Qt::KeyboardModifiers)modifiers);
+
+    return Plasma::ContainmentActions::eventToString(&mouse);
+}
+
 QString CurrentContainmentActionsModel::wheelEventString(QObject *quickWheelEvent)
 {
     const QPoint angleDelta = quickWheelEvent->property("angleDelta").toPoint();
diff --git a/shell/currentcontainmentactionsmodel.h b/shell/currentcontainmentactionsmodel.h
index 505a9bcdf3..aec4e892fa 100644
--- a/shell/currentcontainmentactionsmodel.h
+++ b/shell/currentcontainmentactionsmodel.h
@@ -39,6 +39,7 @@ public:

     Q_INVOKABLE bool isTriggerUsed(const QString &trigger);
     Q_INVOKABLE QString mouseEventString(int mouseButtons, int modifiers);
+    Q_INVOKABLE QString mouseDoubleClickEventString(int mouseButton, int modifiers);
     Q_INVOKABLE QString wheelEventString(QObject *quickWheelEvent);
     Q_INVOKABLE bool append(const QString &action, const QString &plugin);
     Q_INVOKABLE void update(int row, const QString &action, const QString &plugin);
-- 
2.53.0
